from math import comb

def vals(n,r,q):
 a=2*sum(comb(n-1,k) for k in range(r))
 b=2**(q*n)-2*sum(comb(n,k)*(2**q-1)**k for k in range(r) if (r-k)%2)
 c=comb(n,r)*q**r
 return a,b,c
for q in range(2,31):
 found=None
 for n in range(2,401):
  rr=[]
  for r in range(1,n):
   a,b,c=vals(n,r,q)
   if a*b<c*c: rr.append(r)
  if rr:
   found=n,rr
   break
 print(q,found,flush=True)
